settings.custom_css:
/* Pill buttons for all homepage sections (needs Elementor Pro Custom CSS). Not scoped, so it styles every .gw-pill on the page. */
.gw-pill .elementor-button { display: inline-flex; align-items: center; min-height: 52px; transition: opacity .3s; }
.gw-pill .elementor-button:hover { opacity: .85; }
.gw-pill .elementor-button-content-wrapper { align-items: center; }
.gw-pill .elementor-button-icon svg { width: 16px; height: auto; }
.gw-pill--primary .elementor-button-icon, .gw-pill--light .elementor-button-icon { display: flex; align-items: center; justify-content: center; width: 40px; height: 40px; border-radius: 50%; }
.gw-pill--primary .elementor-button-icon { background: #FFFFFF; }
.gw-pill--light .elementor-button-icon { background: #0074BE; }
/* Glacier West overflow safety, 980-1440px (Elementor Pro Custom CSS). Mirrors the _laptop values, so it also works
   when the Laptop breakpoint is NOT enabled in Site Settings > Layout > Breakpoints. Scoped to .gw-sec sections only. */
.gw-sec .e-con, .gw-sec .elementor-widget { min-width: 0; }
.gw-sec .elementor-heading-title, .gw-sec .elementor-widget-text-editor { overflow-wrap: break-word; }
@media (min-width: 1025px) and (max-width: 1366px) {
  .gw-sec > .gw-inner { padding-left: 48px !important; padding-right: 48px !important; }
  .gw-sec .gw-gap-lg { column-gap: 40px !important; }
  .gw-sec .gw-wwb-panel { margin-right: -48px !important; padding: 96px 48px 56px 32px !important; }
  .gw-sec .gw-pad-lg { padding-left: 48px !important; padding-right: 48px !important; }
  .gw-sec .gw-fs-xl .elementor-heading-title, .gw-sec .gw-fs-xl.elementor-widget-text-editor, .gw-sec .gw-fs-xl .elementor-widget-container { font-size: 52px !important; line-height: 1.05 !important; }
  .gw-sec .gw-fs-lg .elementor-heading-title, .gw-sec .gw-fs-lg.elementor-widget-text-editor, .gw-sec .gw-fs-lg .elementor-widget-container { font-size: 44px !important; line-height: 1.2 !important; }
  .gw-sec .gw-fs-md .elementor-heading-title, .gw-sec .gw-fs-md.elementor-widget-text-editor, .gw-sec .gw-fs-md .elementor-widget-container { font-size: 40px !important; }
}
/* Single post hero meta: category as a glass pill */
selector .gw-post-meta .elementor-icon-list-item:first-child a, selector .gw-post-meta .elementor-icon-list-item:first-child .elementor-post-info__terms-list { display: inline-flex; padding: 8px 16px; border-radius: 1000px; background: rgba(255,255,255,0.2); border: 1px solid rgba(255,255,255,0.2); color: #fff; font-size: 12px; line-height: 20px; letter-spacing: 2.4px; text-transform: uppercase; }
selector .gw-post-meta .elementor-icon-list-item:first-child .elementor-post-info__terms-list:before { content: "▲"; color: #00CBFA; font-size: 11px; margin-right: 8px; }
selector .gw-author .elementor-author-box__avatar img { width: 48px; height: 48px; }

/* TOC: left rule per item, active = blue rule + black text */
selector .elementor-toc__body { padding: 12px 0 0 !important; }
selector .elementor-toc__list-item { margin: 0; }
selector .elementor-toc__list-item-text-wrapper { border-left: 1px solid #DBDBDB; padding: 12px 0 12px 14px; }
selector .elementor-toc__list-item-text-wrapper:has(.elementor-item-active) { border-left-color: #0074BE; }
selector .elementor-toc__header { padding: 0 !important; border: 0 !important; }
selector .elementor-toc__list-item-text-wrapper:before { display: none; }

selector .elementor-post-info__item-prefix { color: #8A8A8A; margin-right: 10px; }
selector .elementor-post-info__terms-list { display: inline-flex; flex-wrap: wrap; gap: 10px; font-size: 0; }
selector .elementor-post-info__terms-list-item { font-size: 14px; padding: 8px 16px; border: 1px solid #DBDBDB; border-radius: 1000px; color: #000; }

/* Post cards restyled to the Figma card (Pro Custom CSS). Cards skin markup: thumbnail, badge, text, meta. */
selector .elementor-post__card { display: flex; flex-wrap: wrap; align-items: center; column-gap: 10px; background: transparent; box-shadow: none; border-radius: 0; overflow: visible; }
selector .elementor-post__thumbnail__link { order: 0; width: 100%; margin-bottom: 16px; }
selector .elementor-post__thumbnail { border-radius: 24px; overflow: hidden; }
selector .elementor-post__badge { position: static !important; order: 1; margin: 0 !important; padding: 0 !important; background: none !important; color: #0074BE !important; font-family: "Clash Grotesk", sans-serif; font-size: 12px; line-height: 20px; letter-spacing: 2.4px; text-transform: uppercase; font-weight: 400; }
selector .elementor-post__meta-data { order: 2; padding: 0 !important; border: 0 !important; margin: 0; }
selector .elementor-post__meta-data:before { content: "·"; margin-right: 10px; color: #8A8A8A; }
selector .elementor-post__text { order: 3; width: 100%; padding: 12px 0 0 !important; margin: 0 !important; display: flex; flex-direction: column; gap: 12px; }
selector .elementor-post__title, selector .elementor-post__excerpt p { margin: 0; }
selector .elementor-post__read-more { display: inline-flex; align-items: center; gap: 12px; }
selector .elementor-post__read-more:after { content: ""; width: 32px; height: 32px; border-radius: 50%; background: #0074BE url("https://wordpress-1619480-6775513.cloudwaysapps.com/wp-content/uploads/2026/07/Vector.svg") center / 14px auto no-repeat; }
selector .elementor-post__avatar { display: none; }
selector .elementor-post__card { background: #fff; border-radius: 24px; overflow: hidden; padding-bottom: 28px; }
selector .elementor-post__thumbnail { border-radius: 24px 24px 0 0; }
selector .elementor-post__badge { margin-left: 28px !important; }
selector .elementor-post__text { padding: 8px 28px 0 !important; }
